mapper.select:
SELECT vfp.finprod_market_id as bondid, vfp.finprod_abbr as bondname, vfp.FINPROD_TYPE as finprodType, DATE_FORMAT(vfp.vdate,'%Y-%m-%d') as vdate1, DATE_FORMAT(vfp.mdate,'%Y-%m-%d') as mdate1, vfp.coupon_species as couponType, vfp.coupon_species as couponTypeCode, fpt.type_1 as bondtype, fpt.type_1 as bondtypeCode, (fccr.yield)*100 as rate, fccr2.basis as basis, vfp.ISSUE_PRICE as price, vfp.finprod_name as finprodName, vfp.finprod_id as finprodId FROM FIN_PRODUCT vfp left join (select * from FIN_CASH_CALC_RULE fccr where 1 = 1 and fccr.eff_date = (select max(a.eff_date) from FIN_CASH_CALC_RULE a where a.finprod_id = fccr.finprod_id and a.finprod_type = a.finprod_type)) fccr on vfp.finprod_id = fccr.finprod_id and vfp.finprod_type = fccr.finprod_type left join (select * from FIN_CASH_CALC_RULE fccr2 where 1 = 1 and fccr2.eff_date = (select min(a.eff_date) from FIN_CASH_CALC_RULE a where a.finprod_id = fccr2.finprod_id and a.finprod_type = a.finprod_type)) fccr2 on vfp.finprod_id = fccr2.finprod_id and vfp.finprod_type = fccr2.finprod_type left join FIN_PRODUCT_TYPE fpt on vfp.finprod_id = fpt.finprod_id where vfp.FINPROD_TYPE = 'F01'
AND (vfp.finprod_id in
null) or vfp.finprod_id in (
#{bond}
)
AND (vfp.coupon_species in
null) or vfp.coupon_species in (
#{couponType}
)
AND fpt.type_1 in
#{bondType}
AND vfp.vdate >= STR_TO_DATE(#{vDateBegin},'%Y-%m-%d')
AND vfp.vdate <=STR_TO_DATE(#{vDateEnd},'%Y-%m-%d')
AND vfp.mdate >=STR_TO_DATE(#{mDateBegin},'%Y-%m-%d')
AND vfp.mdate <= STR_TO_DATE(#{mDateEnd},'%Y-%m-%d')
GROUP BY vfp.finprod_market_id, vfp.finprod_abbr, vfp.FINPROD_TYPE, vfp.vdate, vfp.mdate, vfp.coupon_species, fpt.type_1, fccr.yield, fccr2.basis, vfp.ISSUE_PRICE, vfp.finprod_name, vfp.finprod_id
